// secrets-veil: register.ts - function hooks registration
// Generated by OrchestKit mod build
//
// Hook surface (per brief):
// - tool.call{}: mask r.text and string leaves of r.result
// - ui.render{component=ToolResult}: overlay with hover-reveal
// - ui.render{component=CommandOutput}: overlay with hover-reveal
// - command.register{} /veil: terminal fallback reveal
// - session.start{}: build mask table from env names + patterns
//
// Footprint (validate):
// hooks: session.start{}, tool.call{}, ui.render{component=ToolResult},
//        ui.render{component=CommandOutput}, command.register{}, ui.press{}
// calls: $.env.get, $.ui.invalidate
// negative: no process.run, no http.fetch, no store.*, no ui.log

import { buildTable, mask, DEFAULT_PATTERNS } from "../src/mask";
import { walkAndMask } from "../src/tree";
import type { RenderNode } from "../src/tree";
import type {
  MaskSpan,
  MaskTable,
  Register,
  RevealedState,
  ToolCallEvent,
  ToolCallResult,
  UIRenderEvent,
  DollarAPI,
} from "../src/types";

// Module-scope state (per brief)
let maskTable: MaskTable = { entries: [] };
const revealedState: RevealedState = { revealed: new Set() };

// Env names loaded from configs/env-names.json (generated by script)
// Import as JSON - requires --experimental-json-modules or bundling
let envNames: readonly string[] = [];

export const register: Register = (on) => {
  // session.start: build mask table from env names and patterns
  on("session.start", {}, async ($, e, next) => {
    // Load env names from config (names only, never values)
    try {
      // Dynamic import for JSON config
      const configModule = (await import("../configs/env-names.json", {
        with: { type: "json" },
      })) as { default?: { names?: string[] }; names?: string[] };
      envNames = configModule.default?.names ?? configModule.names ?? [];
    } catch {
      // Config may not exist in fresh install; use empty array
      envNames = [];
    }

    // Fetch env values via $.env.get (safe: references only, no I/O on hot path)
    const envValues: Record<string, string> = {};
    for (const name of envNames) {
      try {
        const value = await $.env.get(name);
        if (value !== undefined && value !== "") {
          envValues[name] = value;
        }
      } catch {
        // Env var may not be set; skip silently
      }
    }

    // Build the mask table
    maskTable = buildTable(envNames, envValues, DEFAULT_PATTERNS);

    return next(e);
  });

  // tool.call: mask result before model sees it
  on("tool.call", {}, async ($, e, next) => {
    const r = await next(e);

    // If denied, pass through unchanged
    if (r && "deny" in r && r.deny) {
      return r;
    }

    // Mask text and result leaves
    const maskedResult: ToolCallResult = { ...r };

    // Mask r.text if present
    if (r && "text" in r && typeof r.text === "string") {
      const masked = mask(r.text, maskTable);
      maskedResult.text = masked.text;
    }

    // Mask result string leaves (Bash: stdout, stderr; Read: content)
    if (r && "result" in r && r.result) {
      maskedResult.result = maskResultObject(r.result, maskTable);
    }

    // Add context annotation (per brief)
    if (maskedResult.text !== r?.text || maskedResult.result !== r?.result) {
      maskedResult.context = ["[secrets-veil] N values covered"];
    }

    // Also mask on isError
    if (r && "isError" in r && r.isError) {
      if ("text" in r && typeof r.text === "string") {
        const masked = mask(r.text, maskTable);
        maskedResult.text = masked.text;
      }
    }

    return maskedResult;
  });

  // ui.render ToolResult: overlay with hover-reveal
  on("ui.render", { component: "ToolResult" }, async ($, e, next) => {
    const tree = await next(e);

    if (!e.requestId) return tree;

    // Get spans for this request (from module-scope)
    const spans = getSpansForRequest(e.requestId);

    if (spans.length === 0) return tree;

    // Build overlay tree
    const overlayTree = walkAndMask(tree as RenderNode, spans);

    return overlayTree;
  });

  // ui.render CommandOutput: overlay with hover-reveal
  on("ui.render", { component: "CommandOutput" }, async ($, e, next) => {
    const tree = await next(e);

    if (!e.requestId) return tree;

    const spans = getSpansForRequest(e.requestId);

    if (spans.length === 0) return tree;

    return walkAndMask(tree as RenderNode, spans);
  });

  // command.register /veil: terminal fallback reveal
  on("command.register", { command: "/veil" }, async ($, e, next) => {
    // Register the /veil command
    // The actual reveal is handled by ui.press below
    return next(e);
  });

  // ui.press: handle reveal button press
  on("ui.press", {}, async ($, e, next) => {
    const result = await next(e);

    // Toggle reveal for requestId
    if (e.requestId) {
      if (revealedState.revealed.has(e.requestId)) {
        revealedState.revealed.delete(e.requestId);
      } else {
        revealedState.revealed.add(e.requestId);
      }
      $.ui.invalidate("ui.render");
    }

    return result;
  });
};

// Helper: mask string leaves in result object
function maskResultObject(obj: unknown, table: MaskTable): unknown {
  if (typeof obj === "string") {
    return mask(obj, table).text;
  }
  if (Array.isArray(obj)) {
    return obj.map((item) => maskResultObject(item, table));
  }
  if (obj && typeof obj === "object") {
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      // Mask known string fields (Bash: stdout, stderr; Read: content)
      if (key === "stdout" || key === "stderr" || key === "content") {
        result[key] = typeof value === "string" ? mask(value, table).text : value;
      } else {
        result[key] = maskResultObject(value, table);
      }
    }
    return result;
  }
  return obj;
}

// Placeholder: get spans for a request (would track in real impl)
function getSpansForRequest(_requestId: string): MaskSpan[] {
  // In real impl, we'd track spans per request in module scope
  // For now, return empty (test coverage via mock)
  return [];
}

// Export for testing
export { maskTable, revealedState, mask, buildTable, DEFAULT_PATTERNS };
